-- Migration 0013 — Phase 2: payment idempotency backed by real DB constraints.
--
-- Part 1 was generated by `drizzle-kit generate` from the schema change in
-- src/schema/idempotency-records.ts. Part 2 was added by hand, because
-- drizzle-kit structurally cannot emit it (see below).
--
-- NOTE ON THE JOURNAL TIMESTAMP: drizzle-kit stamped this entry with the
-- wall-clock time, which is EARLIER than 0012_seed_plans' hand-written
-- "when" (1791800000000). drizzle-orm's migrator only applies a migration
-- whose "when" is greater than the newest created_at already recorded in
-- __drizzle_migrations, so that stamp would have made every already-migrated
-- database silently skip this file. _journal.json was set to 1791900000000.

-- Part 1 (gap register D8): store the request fingerprint at claim time.
-- NOT NULL DEFAULT '' so it can be added to a live table without a backfill;
-- '' means "legacy row, hash unknown". It is intentionally NOT part of
-- idx_idempotency_composite — see the schema file's docstring for why.
ALTER TABLE "idempotency_records" ADD COLUMN IF NOT EXISTS "request_hash" text DEFAULT '' NOT NULL;
--> statement-breakpoint

-- Part 2 (gap register D3): the duplicate-charge unique index that
-- src/schema/transactions.ts has always declared, and that
-- meta/0012_snapshot.json (incorrectly) already recorded as existing, but that
-- no migration 0000-0012 ever created. Because the snapshot already contained
-- it, `drizzle-kit generate` never emitted it and `drizzle-kit check` could
-- not notice. Its definition here matches the snapshot entry exactly, so the
-- snapshot chain and the real migrated schema now agree.
--
-- NULL idempotency_key values (payments made without a key) are distinct
-- under a Postgres unique index, so they never collide — intended.
--
-- IF NOT EXISTS: databases built with `drizzle-kit push` (which reads
-- schema.ts directly) already have this index.
--
-- Pre-check: if a database already holds duplicate keyed transactions (i.e.
-- the double-charge this index exists to prevent has already happened), fail
-- loudly with an actionable message instead of a bare 23505. Those rows are
-- payment records and must be reconciled by a human, never auto-deleted.
DO $$
DECLARE
  dup_groups integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE schemaname = current_schema() AND indexname = 'idx_transactions_idempotency'
  ) THEN
    SELECT count(*) INTO dup_groups FROM (
      SELECT 1 FROM "transactions"
      WHERE "idempotency_key" IS NOT NULL
      GROUP BY "app_id", "tenant_id", "idempotency_key"
      HAVING count(*) > 1
    ) d;
    IF dup_groups > 0 THEN
      RAISE EXCEPTION 'migration 0013: % (app_id, tenant_id, idempotency_key) group(s) in "transactions" already have duplicate rows (prior double charges). Reconcile them manually, then re-run migrations. Find them with: SELECT app_id, tenant_id, idempotency_key, array_agg(id) FROM transactions WHERE idempotency_key IS NOT NULL GROUP BY 1,2,3 HAVING count(*) > 1;', dup_groups;
    END IF;
  END IF;
END
$$;
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "idx_transactions_idempotency" ON "transactions" USING btree ("app_id","tenant_id","idempotency_key");
